-- Run inside a transaction and roll back. No HTTP requests are made.
do $$
declare l uuid; a uuid; j public.crm_sonali_webhook_outbox%rowtype; p jsonb; n integer;
begin
 if (select enabled from crm_sonali_webhook_settings) then raise exception 'Must start paused'; end if;
 if not crm_sonali_rann_destination('Rann Utsav – The Tent City') or not crm_sonali_rann_destination('Rann Tent Resort') or not crm_sonali_rann_destination('Namak') or crm_sonali_rann_destination('Statue of Unity') or crm_sonali_rann_destination('Mumbai to Rann of Kutch travel guide') then raise exception 'Destination filter failed'; end if;
 insert into leads(name,phone,status,assigned_to,trip_details,source) values('INTERNAL ROLLBACK TEST','+910000000000','New','2','{"destination":"Rann Utsav"}','WhatsApp Click - rannutsavtickets.in') returning id into l;
 if exists(select 1 from crm_sonali_webhook_outbox where lead_id=l) then raise exception 'Paused webhook queued lead'; end if;
 perform crm_sonali_webhook_settings_write('{"target_url":"https://example.com/webhook","enabled":true}');
 insert into leads(name,phone,status,assigned_to,trip_details,source) values('INTERNAL ROLLBACK TEST','+910000000000','New','2','{"destination":"Rann Utsav"}','WhatsApp Click - rannutsavtickets.in') returning id into l;
 select * into j from crm_sonali_webhook_outbox where lead_id=l;
 if j.event is distinct from 'lead.created' or j.next_attempt_at<j.occurred_at+interval '5 minutes' then raise exception 'Creation / minimum hold failed'; end if;
 if exists(select 1 from crm_sonali_webhook_claim(20) where lead_id=l) then raise exception 'Claimed held job'; end if;
 update leads set name='INTERNAL UPDATED TEST' where id=l;
 if (select count(*) from crm_sonali_webhook_outbox where lead_id=l)<>1 then raise exception 'Duplicate on unrelated update'; end if;
 update leads set assigned_to='admin' where id=l;
 if (select state from crm_sonali_webhook_outbox where id=j.id)<>'cancelled' then raise exception 'Reassignment failed to cancel'; end if;
 update leads set assigned_to='2' where id=l;
 select * into j from crm_sonali_webhook_outbox where lead_id=l and state='pending';
 if j.event is distinct from 'lead.assigned' or j.previous_owner is distinct from 'admin' or j.next_attempt_at<j.occurred_at+interval '5 minutes' then raise exception 'Assignment event / hold failed'; end if;
 update crm_sonali_webhook_outbox set next_attempt_at=now()-interval '1 second' where id=j.id;
 select * into j from crm_sonali_webhook_claim(20) where id=j.id;
 p:=crm_sonali_webhook_preflight(j.id,j.lease_token);
 if p#>>'{body,data,owner}' is distinct from '2' or p#>>'{body,data,owner_name}' is distinct from 'Sonali' or p#>>'{body,data,phone}' is distinct from '+910000000000' or p#>>'{body,data,destination}' is distinct from 'Rann Utsav' or p#>>'{body,data,ref_id}' is null then raise exception 'Payload failed'; end if;
 perform crm_sonali_webhook_finish(j.id,j.lease_token,503,'Receiver returned HTTP 503');
 if not exists(select 1 from crm_sonali_webhook_outbox where id=j.id and state='pending' and attempts=1 and next_attempt_at>=now()+interval '60 seconds') then raise exception 'Retry failed'; end if;
 update leads set last_customer_message_at=now() where id=l;
 update crm_sonali_webhook_outbox set next_attempt_at=now() where id=j.id;
 select * into j from crm_sonali_webhook_claim(20) where id=j.id;
 p:=crm_sonali_webhook_preflight(j.id,j.lease_token);
 if p is not null or (select last_error from crm_sonali_webhook_outbox where id=j.id)<>'customer_already_messaged' then raise exception 'Customer cancellation failed'; end if;
 insert into leads(name,status,assigned_to,trip_details,source) values('INTERNAL ROLLBACK TEST','New','2','{"destination":"Statue of Unity"}','Website') returning id into a;
 if exists(select 1 from crm_sonali_webhook_outbox where lead_id=a) then raise exception 'Unrelated destination queued'; end if;
 insert into leads(name,status,assigned_to,trip_details,source) values('INTERNAL ROLLBACK TEST','New','admin','{"destination":"Rann Utsav"}','Website') returning id into a;
 if exists(select 1 from crm_sonali_webhook_outbox where lead_id=a) then raise exception 'Wrong owner queued'; end if;
 update leads set assigned_to='2' where id=a;
 select * into j from crm_sonali_webhook_claim(20) where lead_id=a;
 update leads set trip_details='{"destination":"Goa"}' where id=a;
 if crm_sonali_webhook_preflight(j.id,j.lease_token) is not null then raise exception 'Destination recheck failed'; end if;
 update leads set assigned_to='admin',trip_details='{"destination":"Rann Tent Resort"}' where id=a;
 update leads set assigned_to='2' where id=a;
 select * into j from crm_sonali_webhook_claim(20) where lead_id=a;
 perform crm_sonali_webhook_finish(j.id,j.lease_token,200,'');
 if (select state from crm_sonali_webhook_outbox where id=j.id)<>'delivered' then raise exception 'Success failed'; end if;
 if has_table_privilege('anon','crm_sonali_webhook_settings','select') or has_function_privilege('authenticated','crm_sonali_webhook_preflight(uuid,uuid)','execute') then raise exception 'Public access not revoked'; end if;
 perform crm_sonali_webhook_settings_write('{"enabled":false}');
 if exists(select 1 from crm_sonali_webhook_outbox where state in ('pending','processing')) then raise exception 'Pause did not cancel queue'; end if;
end;$$;
select 'Sonali webhook rollback checks passed' as result;
